  Ad_bridge_partner_ad_message_rocket_fuel: "L’intégration de la plateforme Origin Platform de Rocket Fuel dans Marketo permet aux professionnels du marketing de stimuler un marketing sans précédent et un retour sur investissement dans les publicités numériques, offrant des expériences de connexion client multicanaux permanentes.<br/><br/><a href='http://launchpoint.marketo.com/rocket-fuel/1594-rocket-fuel-origin-platform' target='_blank'>En savoir plus</a>",
  Ad_bridge_partner_ad_message_turn: "L’intégration de Digital Hub de Turn dans Marketo permet aux professionnels du marketing d’augmenter la conversion et de réduire les coûts d’acquisition client en atteignant des publics pertinents via des annonces, appareils mobiles, vidéos, réseaux sociaux et programmes télévisés.<br/><br/><a href='http://launchpoint.marketo.com/turn/1288-turn-dmp' target='_blank'>En savoir plus</a>",
